-heading{display:flex;align-items:center;gap:11px;padding:12px;border-radius:11px;background:#edf5f3;color:#246765}.item-heading div{display:grid;gap:3px}.item-heading strong{color:#18211e;font-size:17px}.item-heading small{color:#53615c;font-size:15px}.detail-section{margin-top:21px}.detail-section h3,.payment-card h3,.schedule-section h3{margin:0 0 12px;color:#26322e;font:600 18px var(--font-verly-display)}.timeline{display:grid;gap:0}.timeline-row{position:relative;display:flex;align-items:flex-start;gap:11px;min-height:60px;color:#5a6763}.timeline-row:not(:last-child)::after{position:absolute;top:34px;left:15px;width:2px;height:26px;background:#d9e2de;content:""}.timeline-row.complete{color:#1e7a3c}.timeline-row.active{color:#246765}.timeline-icon{display:grid;z-index:1;place-items:center;width:32px;height:32px;border:1px solid #ccd7d2;border-radius:50%;background:#fff}.timeline-row.complete .timeline-icon{border-color:#1e7a3c;background:#e9f4ec}.timeline-row.active .timeline-icon{border-color:#2e7d7a;background:#e4f1ef}.timeline-row>span:last-child{display:grid;gap:3px;padding-top:1px}.timeline-row strong{color:#26322e;font-size:16px}.timeline-row small{color:#5a6763;font-size:15px}.payment-card{display:grid;gap:8px;margin-top:9px;padding:15px;border:1px solid #dce3e0;border-radius:12px;background:#fbfcfb}.payment-card h3{margin-bottom:3px}.payment-card>div{display:flex;justify-content:space-between;gap:10px;color:#4e5a56;font-size:15px}.payment-card>div strong{color:#26322e;font:600 15px var(--font-verly-mono)}.payment-card .paid-line strong{color:#1e7a3c}.payment-card .due-line{margin:4px -3px -3px;padding:10px 3px 0;border-top:1px solid #e1e6e3;color:#8b4104}.payment-card .due-line strong{color:#a84f06}.payment-card>small{color:#64706c;font-size:15px}.address-section p{display:flex;align-items:flex-start;gap:7px;margin:0 0 6px;color:#293632;font-size:15px;line-height:1.4}.address-section p svg{flex:none;color:#2e7d7a}.address-section>small{padding-left:24px;