.preview-dialog{inset:0;width:min(720px,calc(100vw - 32px));height:auto;max-height:90dvh;margin:auto;border-radius:16px;box-shadow:0 22px 70px #111a1838;overflow:auto}.dialog-shell{max-height:90dvh}
